PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE chats (
                  id integer primary key autoincrement,
                  platform text not null,
                  browser text not null,
                  chat_key text not null,
                  title text,
                  phone text,
                  last_seen_at text,
                  created_at text not null,
                  updated_at text not null, last_synced_at TEXT,
                  unique(platform, chat_key)
                );
CREATE TABLE messages (
                  id integer primary key autoincrement,
                  chat_id integer references chats(id) on delete cascade,
                  platform text not null,
                  direction text,
                  sender text,
                  body text,
                  sent_at text,
                  raw text,
                  created_at text not null
                , message_hash TEXT, sent_at_parsed TEXT, sent_at_unix REAL);
CREATE TABLE transcripts (
                  id integer primary key autoincrement,
                  platform text not null,
                  chat_key text not null,
                  file_path text not null,
                  message_count integer not null,
                  started_at text,
                  ended_at text,
                  created_at text not null
                );
CREATE TABLE sync_logs (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        platform TEXT NOT NULL,
        chat_key TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'started',
        messages_before INTEGER DEFAULT 0,
        messages_after INTEGER DEFAULT 0,
        messages_inserted INTEGER DEFAULT 0,
        started_at TEXT NOT NULL,
        ended_at TEXT,
        error_message TEXT,
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX idx_msg_unique_hash 
    ON messages(chat_id, message_hash);
COMMIT;
